package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Node;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class Node_absUrl_TriageGen2Test {

    @Test
    public void testAbsUrl_EmptyAttributeKey() {
        Node node = new Node("http://example.com");
        assertThrows(NullPointerException.class, () -> node.absUrl(""));
    }

    @Test
    public void testAbsUrl_NoBaseUrl() {
        Node node = new Node("");
        String relUrl = "http://example.com/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAlreadyAbsolute() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlRelative() {
        Node node = new Node("http://example.com");
        String relUrl = "/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlRelativeWithTrailingSlash() {
        Node node = new Node("http://example.com");
        String relUrl = "/path/";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path/", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlRelativeWithLeadingSlash() {
        Node node = new Node("http://example.com");
        String relUrl = "/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlRelativeWithMultipleSlashes() {
        Node node = new Node("http://example.com");
        String relUrl = "/path//";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path/", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlRelativeWithDot() {
        Node node = new Node("http://example.com");
        String relUrl = "./path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlRelativeWithDoubleDot() {
        Node node = new Node("http://example.com");
        String relUrl = "../path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAbsolute() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAbsoluteWithTrailingSlash() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com/path/";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path/", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAbsoluteWithLeadingSlash() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAbsoluteWithMultipleSlashes() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com/path//";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path/", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAbsoluteWithDot() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com./path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlAbsoluteWithDoubleDot() {
        Node node = new Node("http://example.com");
        String relUrl = "http://example.com../path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("http://example.com/path", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlInvalid() {
        Node node = new Node("http://example.com");
        String relUrl = "invalid url";
        String absUrl = node.absUrl(relUrl);
        assertEquals("", absUrl);
    }

    @Test
    public void testAbsUrl_RelUrlNull() {
        Node node = new Node("http://example.com");
        String relUrl = null;
        String absUrl = node.absUrl(relUrl);
        assertEquals("", absUrl);
    }

    @Test
    public void testAbsUrl_BaseUriInvalid() {
        Node node = new Node("invalid uri");
        String relUrl = "http://example.com/path";
        String absUrl = node.absUrl(relUrl);
        assertEquals("", absUrl);
    }
}
